package dev.pmo.exportweb;
import java.util.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.core.oidc.user.OidcUser;
import org.springframework.security.web.csrf.CsrfToken;
import org.springframework.http.*;
@RestController class InquiryApi {
 private final OpsAccess access;private final ProjectStore projects;private final InquiryService service;
 InquiryApi(OpsAccess access,ProjectStore projects,InquiryService service){this.access=access;this.projects=projects;this.service=service;}
 private OpsAccess.Scope scope(HttpServletRequest r,OidcUser user){return access.authorize(r.getServerName().toLowerCase(Locale.ROOT),user,null);}
 private static String e(String s){return ContentHtml.text(s);}
 @GetMapping(value="/inquiry",produces=MediaType.TEXT_HTML_VALUE) ResponseEntity<String> form(HttpServletRequest r,CsrfToken csrf){var s=access.resolve(r.getServerName());var p=projects.published(s);String name=e(p.websiteCompany().name());String html="<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Contact · "+name+"</title><style>body{font:16px system-ui;max-width:760px;margin:auto;padding:24px;color:#193d43}form{display:grid;grid-template-columns:1fr 1fr;gap:16px}input,textarea{box-sizing:border-box;width:100%;padding:10px;font:inherit}label{display:block}.wide{grid-column:1/-1}button{padding:12px;font:inherit}@media(max-width:600px){form{grid-template-columns:1fr}}</style></head><body><a href='/'>Home / 返回</a><h1>Contact · "+name+"</h1><p>Send a business inquiry. / 提交业务询盘。</p><form method='post' action='/inquiry'><input type='hidden' name='id' value='"+UUID.randomUUID()+"'><input type='hidden' name='"+e(csrf.getParameterName())+"' value='"+e(csrf.getToken())+"'><label>Name / 姓名<input name='name' maxlength='120' required></label><label>Business email / 邮箱<input type='email' name='email' maxlength='254' required></label><label>Company / 公司<input name='company' maxlength='160' required></label><label>Country code / 国家代码<input name='country' maxlength='2' pattern='[A-Za-z]{2}' placeholder='US / CN / JP' required></label><label class='wide'>Subject / 主题<input name='subject' maxlength='180' required></label><label class='wide'>Message / 内容<textarea name='message' maxlength='5000' rows='7' required></textarea></label><label hidden>Leave empty<input name='website' tabindex='-1' autocomplete='off'></label><p class='wide'>Your contact details and message will be shared with this website’s business to respond to this inquiry. / 本站经营者将使用您提供的联系方式与内容处理本次询盘。</p><button class='wide'>Send inquiry / 提交询盘</button></form></body></html>";return ResponseEntity.ok().header("Cache-Control","no-store").body(html);}
 @PostMapping(value="/inquiry",produces=MediaType.TEXT_HTML_VALUE) ResponseEntity<String> submit(HttpServletRequest r,@ModelAttribute InquiryService.Input input){service.accept(access.resolve(r.getServerName()),input,r.getSession().getId());return ResponseEntity.status(303).header("Cache-Control","no-store").location(java.net.URI.create("/inquiry/received")).build();}
 @GetMapping(value="/inquiry/received",produces=MediaType.TEXT_HTML_VALUE) ResponseEntity<String> received(){return ResponseEntity.ok().header("Cache-Control","no-store").body("<!doctype html><html lang='en'><meta charset='utf-8'><title>Inquiry received</title><h1>Inquiry received / 询盘已提交</h1><a href='/'>Home / 返回网站</a></html>");}
 @GetMapping("/api/v1/inquiries") List<Map<String,Object>> list(HttpServletRequest r,@AuthenticationPrincipal OidcUser user,@RequestParam(defaultValue="0")int offset){return service.list(scope(r,user),offset);}
 @GetMapping("/api/v1/inquiries/{id}") Map<String,Object> read(HttpServletRequest r,@AuthenticationPrincipal OidcUser user,@PathVariable UUID id){return service.read(scope(r,user),id);}
 @GetMapping("/api/v1/inquiries/summary") Map<String,Object> summary(HttpServletRequest r,@AuthenticationPrincipal OidcUser user,@RequestParam String from,@RequestParam String to){return service.summary(scope(r,user),from,to);}
 record Update(long revision,String state,String note){}
 @PutMapping("/api/v1/inquiries/{id}") Map<String,Boolean> update(HttpServletRequest r,@AuthenticationPrincipal OidcUser user,@PathVariable UUID id,@RequestBody Update input){service.update(scope(r,user),id,input.revision(),input.state(),input.note());return Map.of("saved",true);}
 @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<?> invalid(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("message",Objects.toString(e.getMessage(),"输入无效")));}
}
